//! LeekWallet Zcash Companion — Tauri backend.
//!
//! Moves bytes between the frontend and the device (no protocol parsing, no
//! key handling: the codec lives in `packages/core` where it can be tested
//! under plain Node, and the device decides everything that matters), and,
//! with the `zcash-wallet` feature, runs the Zcash wallet (zecz) the
//! webview drives. Zcash only.
//!
//! This lives in a library rather than in `main.rs` because Android has no
//! `main()`: the APK loads a shared object and the JVM calls the entry point
//! generated by `tauri::mobile_entry_point`. Desktop's `main.rs` calls the same
//! `run()`, so both platforms boot identical code.

// Both transports are present on every platform since T59.
//
// Each transport crate carries two backends behind one API and picks between
// them at build time: `leek-transport-serial` is the `serialport` crate on
// desktop and `tauri-plugin-serialplugin`'s USB Host driver on Android;
// `leek-transport-ble` is btleplug on desktop and `tauri-plugin-blec` on
// Android. Both modules below are therefore the same code on both platforms,
// and so are the commands they export. See each crate's `android.rs` for why
// the phone needs a different way in rather than a different transport.
mod ble;
mod serial;

// The link across the app's lifecycle: closed after a while in the
// background, on close, and when a new webview finds one left open.
mod link;

// The Zcash wallet (feature `zcash-wallet`): the desktop app's own modules,
// compiled in from desktop/src-tauri/src rather than copied, so importing,
// syncing, proposing, finishing, the address book and the per-network
// server settings are one implementation with the desktop's tests behind
// it. `backend` keeps its name because `hardware` refers to it as
// `crate::backend`. Only zwallet.rs is the Companion's own: the commands,
// with the board left to the webview's session. Parts of the desktop
// modules (its own Rust pairing, swap helpers) are unused here.
#[cfg(feature = "zcash-wallet")]
#[allow(dead_code)]
#[path = "../../../../desktop/src-tauri/src/backend.rs"]
mod backend;
#[cfg(feature = "zcash-wallet")]
#[allow(dead_code)]
#[path = "../../../../desktop/src-tauri/src/hardware.rs"]
mod zhardware;
#[cfg(feature = "zcash-wallet")]
#[allow(dead_code)]
#[path = "../../../../desktop/src-tauri/src/contacts.rs"]
mod zcontacts;
#[cfg(feature = "zcash-wallet")]
#[allow(dead_code)]
#[path = "../../../../desktop/src-tauri/src/settings.rs"]
mod zsettings;
#[cfg(feature = "zcash-wallet")]
mod zwallet;

// The board's output to disk: the `.zsig` of a PCZT signed on the board,
// written where the user can pick it up (the webviews cannot save a file).
mod files;

/* Firmware flashing (T65). Compiled unconditionally so the capability query and
 * the image checks -- the reviewable part, and the part with tests -- always
 * exist; only the espflash-backed half is behind the `flasher` feature.
 *
 * The allow follows from that split: without the feature, the digest and chip
 * checks are reached only from the tests, so the compiler is right that nothing
 * calls them and wrong that they are dead. It silences "you have not called
 * this yet", not a real absence. */
#[cfg_attr(
    not(all(feature = "flasher", not(target_os = "android"))),
    allow(dead_code)
)]
mod flash;

/// Which transports this build actually has behind it.
///
/// A real capability query, replacing the frontend's old habit of sniffing the
/// user agent for "Android". The frontend must not decide from the presence of
/// an `invoke` bridge that a device is reachable: on Android the bridge exists
/// whether or not anything is wired behind it, and a status badge reading
/// "hardware" on a phone connected to nothing is the one lie a wallet UI must
/// never tell.
#[tauri::command]
fn transports() -> Vec<&'static str> {
    // Identical on both platforms now, and deliberately not written as a
    // platform-conditional constant: the honest claim is "both command sets
    // are compiled and their drivers ship in this binary", and after T59 that
    // is true of the phone as well.
    //
    // Claiming "usb" here is a claim that `ports`/`connect`/`request` will
    // work, so on Android it rests on the Kotlin inside
    // `tauri-plugin-serialplugin` being linked into the APK by Tauri's own
    // project generation — not on the Rust happening to compile. An empty port
    // list or a refused permission are runtime answers with their own
    // messages, not reasons to deny the capability; never advertising a
    // transport that fails at first use is the rule, and a transport that
    // needs the user to approve a dialog has not failed.
    vec!["usb", "ble"]
}

/// Let the Linux webview reach a camera, for the Send form's QR scanner.
///
/// WebKitGTK is not Chromium: `enable-media-stream` defaults to off, and every
/// permission request is denied unless the embedder answers it, so
/// `getUserMedia` rejects with NotAllowedError and scanning is dead on Linux.
///
/// Only camera requests are granted, and only because of what this webview is:
/// it loads this app's own bundled UI and no remote page (the CSP has no
/// frame-src and there is no address bar). Microphone, geolocation and the rest
/// are refused, so this cannot become a general-purpose yes. Android needs no
/// code: Tauri's webview client asks the user for the CAMERA permission the
/// manifest declares (ANDROID.md).
#[cfg(target_os = "linux")]
fn allow_camera(window: &tauri::WebviewWindow) {
    use webkit2gtk::{PermissionRequestExt, SettingsExt, UserMediaPermissionRequestExt, WebViewExt};

    if let Err(e) = window.with_webview(|webview| {
        let view = webview.inner();
        if let Some(settings) = WebViewExt::settings(&view) {
            settings.set_enable_media_stream(true);
        }
        view.connect_permission_request(|_, request| {
            use webkit2gtk::glib::object::Cast;
            let media = request.clone().downcast::<webkit2gtk::UserMediaPermissionRequest>().ok();
            match media {
                // The camera; audio is never asked for and is not granted just
                // because it shares the request type.
                Some(m) if m.is_for_video_device() && !m.is_for_audio_device() => request.allow(),
                _ => request.deny(),
            }
            true
        });
    }) {
        // Not fatal: the app works, scanning does not, and the scanner says so.
        eprintln!("could not enable the camera in this webview: {e}");
    }
}

/// Panics, written where `adb logcat -s RustStdoutStderr` (Android) and the
/// terminal (desktop) show them, with the thread and the place. `panic`
/// stays `unwind` (Cargo.toml), so a panicking command fails that call and
/// the app goes on; this is what makes the failure readable afterwards.
fn log_panics() {
    let previous = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let thread = std::thread::current();
        eprintln!("leek-panic: thread '{}' {info}", thread.name().unwrap_or("?"));
        previous(info);
    }));
}

/// Start the app.
///
/// `mobile_entry_point` is what the generated Android project calls; on desktop
/// the attribute expands to nothing and `main.rs` calls this directly.
///
/// Nothing may be inserted between the attribute below and `run()`. Put a new
/// function above this comment, not under it. A function slipped in between
/// silently takes the attribute with it, and because the attribute expands to
/// nothing off-mobile, the desktop build and `cargo check` stay perfectly
/// green — the only symptom is the Android APK failing to link with "does not
/// include required runtime symbols", one build step and several minutes later.
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    log_panics();
    let builder = tauri::Builder::default()
        .manage(ble::Connection::default())
        .manage(serial::Connection::default())
        .manage(link::Lifecycle::default());

    // Registering the plugins is what installs the Android plugin handles the
    // backends call through; without them every call panics with "plugin
    // handle not initialized". Deliberately absent on desktop, where our own
    // btleplug and `serialport` code talks to the hardware directly and a
    // second stack in the process would only be one more thing to go wrong.
    //
    // Nothing is added to `capabilities/default.json` for either: the plugins'
    // own JS commands are never invoked from the webview, only from Rust, so
    // the window is granted no new surface and the CSP is untouched.
    #[cfg(target_os = "android")]
    let builder = builder
        .plugin(tauri_plugin_blec::init())
        .plugin(tauri_plugin_serialplugin::init());

    // Registered on every target, unlike the two above: this one IS called from
    // the webview, for the block-explorer link of a Zcash transaction, which
    // the app builds itself (explorerTx in packages/core/src/zcash.ts).
    let builder = builder.plugin(tauri_plugin_opener::init());

    builder
        .setup(|_app| {
            #[cfg(feature = "zcash-wallet")]
            {
                use tauri::Manager;
                _app.manage(zwallet::ZState::new(_app.handle())?);
            }
            #[cfg(target_os = "linux")]
            {
                use tauri::Manager;
                if let Some(window) = _app.get_webview_window("main") {
                    allow_camera(&window);
                }
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            transports,
            link::link_reset,
            serial::ports,
            serial::connect,
            serial::disconnect,
            serial::request,
            ble::ble_scan,
            ble::ble_connect,
            ble::ble_disconnect,
            ble::ble_request,
            flash::flash_capability,
            flash::flash_ports,
            flash::flash_detect,
            flash::flash_write,
            files::save_download,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_available,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_status,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_import,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_forget,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_sync,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_balances,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_addresses,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_next_address,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_history,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_tip,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_check_address,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_propose_send,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_propose_shield,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_finish,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_set_server,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_contacts,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_contact_save,
            #[cfg(feature = "zcash-wallet")]
            zwallet::zw_contact_remove
        ])
        .build(tauri::generate_context!())
        .expect("failed to start Zcash LeekWallet")
        .run(|app, event| match event {
            /* Android onPause and onResume: the link is closed after a
             * while in the background (link.rs), not at once. */
            #[cfg(mobile)]
            tauri::RunEvent::WindowEvent { event: tauri::WindowEvent::Suspended, .. } => {
                link::suspended(app)
            }
            #[cfg(mobile)]
            tauri::RunEvent::WindowEvent { event: tauri::WindowEvent::Resumed, .. } => {
                link::resumed(app)
            }
            /* Closing: a GATT disconnect now, so the board advertises
             * again instead of keeping a link nobody uses. */
            tauri::RunEvent::Exit => link::closing(app),
            _ => {}
        });
}
